style.css:
body {
    font-family: 'Arial', sans-serif;
    background: linear-gradient(to right, #1c1c1c, #3b3b3b);
    color: #ffffff;
    margin: 0;
    padding: 0;
}

header {
    text-align: center;
    padding: 50px;
    background: rgba(0, 0, 0, 0.7);
}

h1 {
    font-size: 3em;
    text-shadow: 2px 2px 4px rgba(255, 255, 255, 0.3);
}

main {
    padding: 20px;
}

h2 {
    font-size: 2em;
    color: #00ffcc;
}

section {
    border: 2px solid #00ffcc;
    padding: 20px;
    margin: 20px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.1);
}

footer {
    text-align: center;
    padding: 15px;
    background: rgba(0, 0, 0, 0.7);
}
